15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const BASE_PREMIUMS: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	};
25	
26	const basePremiumOf = (items: Item[]): number =>
27	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
28	
29	const quotePremium = (items: Item[]): number => {
30	  const base = basePremiumOf(items);
31	
32	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
33	};
34	
35	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
36	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
37	});
